/**
* Display singles sync results to the user
*/
function displaySinglesSyncResults(result, options, context) {
	const { logger } = context;
	const total = result.created.length + result.updated.length + result.unchanged.length;
	const parts = [];
	if (result.created.length > 0) parts.push(`${result.created.length} created`);
	if (result.updated.length > 0) parts.push(`${result.updated.length} updated`);
	if (result.unchanged.length > 0) parts.push(`${result.unchanged.length} unchanged`);
	const summary = parts.length > 0 ? ` (${parts.join(", ")})` : "";
	logger.success(`Synced ${formatCount(total, "single")}${summary}`);
	if (options.verbose) {
		if (result.created.length > 0) {
			logger.debug("Created singles:");
			for (const slug of result.created) logger.item(slug, 1);
		}
		if (result.updated.length > 0) {
			logger.debug("Updated singles:");
			for (const slug of result.updated) logger.item(slug, 1);
		}
	}
	if (result.errors.length > 0) {
		logger.newline();
		logger.warn(`${result.errors.length} single sync error(s):`);
		for (const err of result.errors) logger.item(`${err.slug}: ${err.error}`, 1);
	}
}
