/**
* Display sync results to the user
*/
function displaySyncResults(result, options, context) {
	const { logger } = context;
	const { sync, relationshipValidation } = result;
	const total = sync.created.length + sync.updated.length + sync.unchanged.length;
	const parts = [];
	if (sync.created.length > 0) parts.push(`${sync.created.length} created`);
	if (sync.updated.length > 0) parts.push(`${sync.updated.length} updated`);
	if (sync.unchanged.length > 0) parts.push(`${sync.unchanged.length} unchanged`);
	const summary = parts.length > 0 ? ` (${parts.join(", ")})` : "";
	logger.success(`Synced ${formatCount(total, "collection")}${summary}`);
	if (sync.errors.length > 0) {
		logger.newline();
		logger.warn(`${sync.errors.length} sync error(s):`);
		for (const err of sync.errors) logger.item(`${err.slug}: ${err.error}`, 1);
	}
	if (!relationshipValidation.valid) {
		logger.newline();
		logger.warn(`${relationshipValidation.errors.length} relationship error(s):`);
		for (const error of relationshipValidation.errors) logger.item(`${error.collection}.${error.field} → ${error.targetCollection}: ${error.reason}`, 1);
	}
	if (relationshipValidation.warnings.length > 0 && options.verbose) {
		logger.newline();
		logger.warn(`${relationshipValidation.warnings.length} relationship warning(s):`);
		for (const warning of relationshipValidation.warnings) logger.item(`${warning.collection}.${warning.field}: ${warning.message}`, 1);
	}
	if (result.removedCollections.length > 0) {
		logger.newline();
		logger.warn(`${result.removedCollections.length} orphaned collection(s) in database:`);
		for (const removed of result.removedCollections) logger.item(removed.slug, 1);
		logger.info("These exist in the database but not in your config.");
	}
	logger.newline();
	if (result.generatedSchemas.length > 0) {
		const dir = getCommonDirectory(result.generatedSchemas);
		logger.success(`Generated ${formatCount(result.generatedSchemas.length, "Drizzle schema")} → ${dir}`);
		if (options.verbose) for (const file of result.generatedSchemas) logger.item(file, 1);
	}
	if (result.generatedZodSchemas.length > 0) {
		const dir = getCommonDirectory(result.generatedZodSchemas);
		logger.success(`Generated ${formatCount(result.generatedZodSchemas.length, "Zod schema")} → ${dir}`);
		if (options.verbose) for (const file of result.generatedZodSchemas) logger.item(file, 1);
	}
	if (result.generatedTypesFile) logger.success(`Generated types → ${result.generatedTypesFile}`);
	if (options.verbose) logWarnings(logger, result.warnings);
	logger.debug(`Sync completed in ${formatDuration(result.durationMs)}`);
}
/**
* Get common directory from a list of file paths
*/
function getCommonDirectory(paths) {
	if (paths.length === 0) return "";
	if (paths.length === 1) {
		const parts = paths[0].split(/[/\\]/);
		parts.pop();
		return parts.join("/") || ".";
	}
	const parts = paths[0].split(/[/\\]/);
	parts.pop();
	return parts.join("/") || ".";
}
